// ============================================
// VALIDATION INPUT - MCP Cost Calculator
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Parametres specifiques au webhook ---
const model = body.model || ctx.model;
const inputTokens = body.input_tokens || ctx.input_tokens || 0;
const outputTokens = body.output_tokens || ctx.output_tokens || 0;
const requests = body.requests || ctx.requests || 1;

if (!model) {
  errors.push('model requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  model: model,
  input_tokens: inputTokens,
  output_tokens: outputTokens,
  requests: requests,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'calculator',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// CALCULATE COST - MCP Cost Calculator
// ============================================

const prevData = $('Validate Input').first().json;

// LLM pricing per 1M tokens (as of 2024)
const PRICING = {
  // OpenAI
  'gpt-4o': { input: 2.50, output: 10.00 },
  'gpt-4o-mini': { input: 0.15, output: 0.60 },
  'gpt-4-turbo': { input: 10.00, output: 30.00 },
  'gpt-4': { input: 30.00, output: 60.00 },
  'gpt-3.5-turbo': { input: 0.50, output: 1.50 },
  'o1-preview': { input: 15.00, output: 60.00 },
  'o1-mini': { input: 3.00, output: 12.00 },

  // Anthropic
  'claude-3-opus': { input: 15.00, output: 75.00 },
  'claude-3-sonnet': { input: 3.00, output: 15.00 },
  'claude-3-haiku': { input: 0.25, output: 1.25 },
  'claude-3.5-sonnet': { input: 3.00, output: 15.00 },

  // Mistral
  'mistral-large': { input: 2.00, output: 6.00 },
  'mistral-medium': { input: 2.70, output: 8.10 },
  'mistral-small': { input: 0.20, output: 0.60 },
  'mistral-7b': { input: 0.25, output: 0.25 },
  'mixtral-8x7b': { input: 0.70, output: 0.70 },

  // Google
  'gemini-1.5-pro': { input: 1.25, output: 5.00 },
  'gemini-1.5-flash': { input: 0.075, output: 0.30 },
  'gemini-1.0-pro': { input: 0.50, output: 1.50 },

  // Embeddings
  'text-embedding-3-small': { input: 0.02, output: 0 },
  'text-embedding-3-large': { input: 0.13, output: 0 },
  'text-embedding-ada-002': { input: 0.10, output: 0 }
};

const model = prevData.model;
const inputTokens = prevData.input_tokens;
const outputTokens = prevData.output_tokens;
const requests = prevData.requests;

const pricing = PRICING[model];

if (!pricing) {
  return {
    success: false,
    error: {
      code: 'UNKNOWN_MODEL',
      message: `Unknown model: ${model}. Available: ${Object.keys(PRICING).join(', ')}`,
      http_status: 400
    },
    _trace: {
      service_response: { error: 'unknown_model', model: model },
      provider: 'calculator',
      mode: 'error',
      latency_ms: Date.now() - prevData.startTime,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  };
}

const inputCost = (inputTokens / 1000000) * pricing.input;
const outputCost = (outputTokens / 1000000) * pricing.output;
const totalCost = (inputCost + outputCost) * requests;

const result = {
  model: model,
  input_tokens: inputTokens,
  output_tokens: outputTokens,
  requests: requests,
  costs: {
    input_cost_usd: inputCost,
    output_cost_usd: outputCost,
    total_cost_usd: totalCost,
    cost_per_request_usd: totalCost / requests
  },
  pricing: {
    input_per_1m: pricing.input,
    output_per_1m: pricing.output,
    currency: 'USD'
  }
};

return {
  success: true,
  data: result,
  meta: {
    provider: 'calculator',
    pricing_date: '2024-12'
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request,
  _trace: {
    service_response: result,
    provider: 'calculator',
    mode: 'success',
    latency_ms: Date.now() - prevData.startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  }
};

